INSERT INTO lkb_entities (entity_id, region_id, category, subcategory, canonical_name, aliases, short_description, educational_usage, grade_suitability, subject_tags, safe_for_word_problem, quantitative_constraints, verification_status, dedup_fingerprint) VALUES ('ctx_ent_3577_inka_01', '35.77', 'mobility', 'railway', 'PT Industri Kereta Api (INKA) Madiun', '{"PT INKA","Pabrik Kereta Api Madiun","INKA"}', 'Pabrik manufaktur sarana perkeretaapian terintegrasi pertama di Asia Tenggara yang memproduksi gerbong penumpang, lokomotif, dan kereta rel listrik di Kota Madiun.', 'Sangat cocok untuk soal Matematika SD materi kecepatan kereta api, jarak rute tempuh, dan kapasitas daya angkut penumpang.', '{4,5,6}', '{matematika,ips}', true, '{"typical_units": "gerbong", "min_val": 4.0, "max_val": 12.0}'::jsonb, 'verified', '3577:pt_industri_kereta_api_inka_madiun') ON CONFLICT (entity_id) DO UPDATE SET short_description = EXCLUDED.short_description, educational_usage = EXCLUDED.educational_usage;
INSERT INTO lkb_entity_evidence (entity_id, source_id, claim, reviewer, verified_at) VALUES ('ctx_ent_3577_inka_01', 'src_pt_inka_official', 'PT INKA (Persero) beroperasi di Kota Madiun sebagai pusat manufaktur perkeretaapian nasional yang memproduksi kereta penumpang untuk PT KAI dan pasar ekspor internasional.', 'member1_rag_engineer', '2026-09-23');
INSERT INTO lkb_entities (entity_id, region_id, category, subcategory, canonical_name, aliases, short_description, educational_usage, grade_suitability, subject_tags, safe_for_word_problem, quantitative_constraints, verification_status, dedup_fingerprint) VALUES ('ctx_ent_3577_pecel_01', '35.77', 'culture', 'culinary', 'Nasi Pecel Madiun', '{"Pecel Madiun","Sambal Pecel Madiun","Pecel Pincuk"}', 'Kuliner khas berbahan aneka sayuran rebus disiram sambal kacang tanah dengan daun jeruk purut, disajikan di atas pincuk daun pisang beserta rempeyek kacang.', 'Bagus untuk soal Matematika penjumlahan dan pengurangan uang kembalian di warung, porsi makanan, serta materi Bahasa Indonesia teks deskripsi kuliner.', '{1,2,3,4,5}', '{matematika,bahasa_indonesia,ips}', true, '{"typical_units": "porsi", "min_val": 1.0, "max_val": 50.0}'::jsonb, 'verified', '3577:nasi_pecel_madiun') ON CONFLICT (entity_id) DO UPDATE SET short_description = EXCLUDED.short_description, educational_usage = EXCLUDED.educational_usage;
INSERT INTO lkb_entity_evidence (entity_id, source_id, claim, reviewer, verified_at) VALUES ('ctx_ent_3577_pecel_01', 'src_pemkot_madiun_official', 'Pecel Madiun merupakan ikon kuliner tradisional kebanggaan Kota Madiun yang diakui sebagai Warisan Budaya Takbenda dengan sentra penjualan di Jalan Cokroaminoto.', 'member1_rag_engineer', '2026-09-23');
INSERT INTO lkb_entities (entity_id, region_id, category, subcategory, canonical_name, aliases, short_description, educational_usage, grade_suitability, subject_tags, safe_for_word_problem, quantitative_constraints, verification_status, dedup_fingerprint) VALUES ('ctx_ent_3577_pasar_besar_01', '35.77', 'built_environment', 'market', 'Pasar Besar Kota Madiun', '{"Pasar Besar Madiun","PBM Madiun"}', 'Pusat perdagangan rakyat terbesar di Kota Madiun yang mempertemukan pedagang komoditas pertanian, bahan pokok, pakaian, dan aneka hasil bumi antardaerah.', 'Cocok untuk soal cerita aritmetika sosial jual beli, timbangan berat (kg/gram), dan konsep kegiatan ekonomi produsen-distributor-konsumen di IPS.', '{2,3,4,5,6}', '{matematika,ips}', true, '{"typical_units": "kg", "min_val": 1.0, "max_val": 100.0}'::jsonb, 'verified', '3577:pasar_besar_kota_madiun') ON CONFLICT (entity_id) DO UPDATE SET short_description = EXCLUDED.short_description, educational_usage = EXCLUDED.educational_usage;
INSERT INTO lkb_entity_evidence (entity_id, source_id, claim, reviewer, verified_at) VALUES ('ctx_ent_3577_pasar_besar_01', 'src_bps_kota_madiun_2024', 'Pasar Besar Madiun menampung ratusan pedagang bahan pokok dan merupakan pusat perputaran roda ekonomi retail utama di Kota Madiun.', 'member1_rag_engineer', '2026-09-23');
INSERT INTO lkb_entities (entity_id, region_id, category, subcategory, canonical_name, aliases, short_description, educational_usage, grade_suitability, subject_tags, safe_for_word_problem, quantitative_constraints, verification_status, dedup_fingerprint) VALUES ('ctx_ent_3577_bengawan_madiun_01', '35.77', 'geography', 'river', 'Sungai Bengawan Madiun', '{"Kali Madiun","Bengawan Madiun"}', 'Sungai utama yang membelah wilayah Madiun, merupakan anak sungai terbesar dari Bengawan Solo yang mengalirkan air dari lereng Gunung Wilis dan Gunung Lawu.', 'Konteks pembelajaran IPA dan IPS mengenai daur air, pencegahan banjir, serta soal Matematika perbandingan debit dan tinggi muka air.', '{4,5,6}', '{ips,bahasa_indonesia}', true, '{"typical_units": "meter", "min_val": 1.0, "max_val": 15.0}'::jsonb, 'verified', '3577:sungai_bengawan_madiun') ON CONFLICT (entity_id) DO UPDATE SET short_description = EXCLUDED.short_description, educational_usage = EXCLUDED.educational_usage;
INSERT INTO lkb_entity_evidence (entity_id, source_id, claim, reviewer, verified_at) VALUES ('ctx_ent_3577_bengawan_madiun_01', 'src_osm_geodata', 'Sungai Bengawan Madiun mengalir melintasi Kota dan Kabupaten Madiun hingga bermuara ke Sungai Bengawan Solo di wilayah Ngawi.', 'member1_rag_engineer', '2026-09-23');
INSERT INTO lkb_entities (entity_id, region_id, category, subcategory, canonical_name, aliases, short_description, educational_usage, grade_suitability, subject_tags, safe_for_word_problem, quantitative_constraints, verification_status, dedup_fingerprint) VALUES ('ctx_ent_3577_brem_01', '35.77', 'culture', 'culinary', 'Brem Padat Tradisional', '{"Brem Madiun","Brem Padat"}', 'Makanan ringan tradisional berbentuk lempengan padat berwarna putih kekuningan hasil fermentasi sari ketan yang meleleh manis dan dingin di lidah.', 'Bagus untuk soal pembagian kardus oleh-oleh, pecahan matematika, dan teks prosedur pengolahan makanan khas daerah.', '{2,3,4,5}', '{matematika,bahasa_indonesia}', true, '{"typical_units": "kotak", "min_val": 1.0, "max_val": 30.0}'::jsonb, 'verified', '3577:brem_padat_tradisional') ON CONFLICT (entity_id) DO UPDATE SET short_description = EXCLUDED.short_description, educational_usage = EXCLUDED.educational_usage;
INSERT INTO lkb_entity_evidence (entity_id, source_id, claim, reviewer, verified_at) VALUES ('ctx_ent_3577_brem_01', 'src_bps_kota_madiun_2024', 'Industri kecil brem padat berpusat di Madiun dan menjadi komoditas oleh-oleh unggulan yang didistribusikan ke berbagai kota di Jawa Timur.', 'member1_rag_engineer', '2026-09-23');
