INSERT INTO lkb_entity_evidence (entity_id, source_id, claim, reviewer, verified_at) VALUES ('ctx_ent_3519_porang_01', 'src_bps_kab_madiun_2024', 'Kabupaten Madiun merupakan salah satu sentra budidaya dan pengolahan tepung umbi porang terbesar di Indonesia dengan kawasan budidaya di Kecamatan Saradan dan Kare.', 'member1_rag_engineer', '2026-09-23');
