INSERT INTO lkb_entities (entity_id, region_id, category, subcategory, canonical_name, aliases, short_description, educational_usage, grade_suitability, subject_tags, safe_for_word_problem, quantitative_constraints, verification_status, dedup_fingerprint) VALUES ('ctx_ent_3520_telaga_sarangan_01', '35.20', 'geography', 'lake', 'Telaga Sarangan Magetan', '{"Danau Pasir Sarangan","Telaga Sarangan"}', 'Danau vulkanik alami seluas 30 hektar di lereng Gunung Lawu pada ketinggian 1.200 mdpl di Kecamatan Plaosan, berhawa sejuk dan menjadi destinasi wisata utama.', 'Cocok untuk soal keliling dan luas danau, perhitungan tiket masuk wisata, dan deskripsi bentang alam pegunungan sejuk.', '{3,4,5,6}', '{matematika,ips,bahasa_indonesia}', true, '{"typical_units": "meter", "min_val": 100.0, "max_val": 1200.0}'::jsonb, 'verified', '3520:telaga_sarangan_magetan') ON CONFLICT (entity_id) DO UPDATE SET short_description = EXCLUDED.short_description, educational_usage = EXCLUDED.educational_usage;
